def lower_bound(arr, target):
    lo, hi = 0, len(arr)          # note: half-open [lo, hi), hi starts at len(arr)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid           # arr[mid] >= target: it COULD be the answer, keep it in range
    return lo

def upper_bound(arr, target):
    lo, hi = 0, len(arr)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if arr[mid] <= target:
            lo = mid + 1
        else:
            hi = mid
    return lo
```

The only difference between the two is a single `<` vs `<=` in the condition — a small change that shifts the boundary being searched for by exactly one position, which is precisely why these two functions are so easy to swap by accident.
